'use client';
import { useState, useEffect, useMemo } from 'react';
import { use } from 'react';
import axios from 'axios';
import { 
  Save as SaveIcon,
  Clear as ClearIcon,
  Person as PersonIcon,
  Search as SearchIcon,
  Group as GroupIcon
} from '@mui/icons-material';
import { useRouter } from 'next/navigation';
import Layout from "/../../components/Layout";

export default function EditGroupe({ params }) {
  // Unwrap the params promise
  const { id } = use(params);
  const [groupe, setGroupe] = useState(null);
  const [eligibleStudents, setEligibleStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudents, setSelectedStudents] = useState([]);
  const router = useRouter();

  // Filter students based on search term
  const filteredStudents = useMemo(() => {
    if (!searchTerm.trim()) return eligibleStudents;
    return eligibleStudents.filter(student => 
      `${student.nom} ${student.prenom}`.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [eligibleStudents, searchTerm]);

  // Fetch group and student data
  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await axios.get(`/api/groupes/${id}/edit`);
        setGroupe(response.data.groupe);
        setEligibleStudents(response.data.eligibleStudents);
        setSelectedStudents(response.data.groupe.etudiants || []);
      } catch (err) {
        console.error("Erreur lors de la récupération des données :", err);
        alert("Erreur lors du chargement des données.");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [id]);

  // Toggle student selection
  const toggleStudentSelection = (student) => {
    setSelectedStudents(prev => {
      const isSelected = prev.some(s => s.idEtudiant === student.idEtudiant);
      if (isSelected) {
        return prev.filter(s => s.idEtudiant !== student.idEtudiant);
      } else {
        return [...prev, student];
      }
    });
  };

  // Save changes to the group
  const saveChanges = async () => {
    try {
      await axios.put(`/api/groupes/${id}/composition`, {
        etudiants: selectedStudents.map(s => s.idEtudiant)
      });
      alert("Groupe mis à jour avec succès");
      router.push('/users/gestiongroupes');
    } catch (err) {
      console.error("Erreur lors de la mise à jour du groupe :", err);
      alert(`Erreur: ${err.response?.data?.message || err.message}`);
    }
  };

  if (loading || !groupe) {
    return (
      <Layout title="Modification du groupe">
        <div className="flex justify-center items-center h-64">
          <p className="text-lg">Chargement des données...</p>
        </div>
      </Layout>
    );
  }

  return (
    <Layout title={`Modification du groupe ${groupe.nomGroupe}`}>
      <div className="p-4 max-w-7xl mx-auto">
        <div className="bg-white rounded-xl shadow-lg p-6 mb-8 border border-gray-200">
          <h2 className="text-xl font-semibold mb-4 text-[#2563EB] flex items-center">
            <GroupIcon className="mr-2" /> Modifier le groupe: {groupe.nomGroupe}
          </h2>
          
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Available Students Column */}
            <div className="bg-gray-50 p-4 rounded-lg">
              <h3 className="font-medium mb-3 text-gray-700 flex justify-between items-center">
                <span>Étudiants disponibles</span>
                <span className="text-sm text-gray-500">{eligibleStudents.length} étudiants</span>
              </h3>
              
              <div className="mb-3 relative">
                <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                  <SearchIcon className="text-gray-400" style={{ fontSize: '1.2rem' }} />
                </div>
                <input
                  type="text"
                  placeholder="Rechercher un étudiant..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full pl-10 p-2 border rounded focus:ring-2 focus:ring-[#b17a56] focus:outline-none"
                />
                {searchTerm && (
                  <button
                    onClick={() => setSearchTerm('')}
                    className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-gray-600"
                  >
                    <ClearIcon style={{ fontSize: '1.2rem' }} />
                  </button>
                )}
              </div>
              
              <div className="overflow-y-auto max-h-96 border rounded bg-white">
                {filteredStudents.length > 0 ? (
                  <ul className="divide-y divide-gray-200">
                    {filteredStudents.map(student => {
                      const isSelected = selectedStudents.some(s => s.idEtudiant === student.idEtudiant);
                      return (
                        <li 
                          key={student.idEtudiant}
                          className={`p-2 cursor-pointer transition-colors flex justify-between items-center ${
                            isSelected ? 'bg-blue-50' : 'hover:bg-gray-50'
                          }`}
                          onClick={() => toggleStudentSelection(student)}
                        >
                          <div className="flex items-center">
                            <PersonIcon className="text-gray-400 mr-2" style={{ fontSize: '1.2rem' }} />
                            <span>{student.nom} {student.prenom}</span>
                          </div>
                          {isSelected ? (
                            <span className="text-green-500 text-xs font-medium">Sélectionné</span>
                          ) : (
                            <span className="text-blue-500 hover:text-blue-700 text-xs font-medium">
                              Sélectionner
                            </span>
                          )}
                        </li>
                      );
                    })}
                  </ul>
                ) : (
                  <div className="p-4 text-center text-gray-500">
                    {searchTerm ? "Aucun étudiant trouvé" : "Aucun étudiant disponible"}
                  </div>
                )}
              </div>
            </div>
            
            {/* Selected Students Column */}
            <div className="bg-gray-50 p-4 rounded-lg">
              <h3 className="font-medium mb-3 text-gray-700 flex justify-between items-center">
                <span>Étudiants du groupe</span>
                <span className="text-sm text-gray-500">{selectedStudents.length} sélectionnés</span>
              </h3>
              
              <div className={`overflow-y-auto max-h-96 border rounded bg-white ${selectedStudents.length > 0 ? '' : 'flex items-center justify-center'}`}>
                {selectedStudents.length > 0 ? (
                  <ul className="divide-y divide-gray-200">
                    {selectedStudents.map(student => (
                      <li 
                        key={student.idEtudiant}
                        className="p-2 hover:bg-red-50 transition-colors flex justify-between items-center"
                      >
                        <div className="flex items-center">
                          <PersonIcon className="text-blue-400 mr-2" style={{ fontSize: '1.2rem' }} />
                          <span>{student.nom} {student.prenom}</span>
                        </div>
                        <button 
                          onClick={() => toggleStudentSelection(student)}
                          className="text-red-500 hover:text-red-700 text-xs font-medium"
                        >
                          Retirer
                        </button>
                      </li>
                    ))}
                  </ul>
                ) : (
                  <div className="p-8 text-center text-gray-500">
                    Sélectionnez des étudiants pour les ajouter au groupe
                  </div>
                )}
              </div>
              
              <div className="mt-4 flex space-x-3">
                <button
                  onClick={saveChanges}
                  className="flex-1 py-2 px-4 bg-[#b17a56] text-white rounded hover:bg-[#8c6244] transition-colors flex items-center justify-center"
                >
                  <SaveIcon className="mr-2" /> Enregistrer les modifications
                </button>
                
                <button
                  onClick={() => router.push('/users/gestiongroupes')}
                  className="flex-1 py-2 px-4 bg-gray-200 text-gray-700 rounded hover:bg-gray-300 transition-colors flex items-center justify-center"
                >
                  <ClearIcon className="mr-2" /> Annuler
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </Layout>
  );
}